export interface ColabNotebookCell {
  cell_type: 'markdown' | 'code';
  source: string[];
  metadata?: Record<string, unknown>;
  execution_count?: null;
  outputs?: never[];
}

export function buildIpynbPayload(title: string, code: string, lessonUrl?: string): string {
  const headerLines = [
    `# ${title}\n`,
    '\n',
    'Generated by **NeuralPath** — Open-Source ML & AI Learning Platform.\n',
  ];
  if (lessonUrl) {
    headerLines.push(`\nLesson reference: ${lessonUrl}\n`);
  }

  const cells: ColabNotebookCell[] = [
    {
      cell_type: 'markdown',
      metadata: {},
      source: headerLines,
    },
    {
      cell_type: 'code',
      metadata: {},
      execution_count: null,
      outputs: [],
      source: code.split('\n').map((line, i, arr) => (i < arr.length - 1 ? `${line}\n` : line)),
    },
  ];

  return JSON.stringify(
    {
      nbformat: 4,
      nbformat_minor: 0,
      metadata: {
        colab: {
          provenance: [],
          name: `${title.toLowerCase().replace(/[^a-z0-9]+/g, '-')}.ipynb`,
        },
        kernelspec: {
          name: 'python3',
          display_name: 'Python 3',
        },
        language_info: {
          name: 'python',
        },
      },
      cells,
    },
    null,
    2
  );
}

export function getColabUrl(colabNotebookPath?: string): string {
  if (colabNotebookPath && colabNotebookPath.startsWith('http')) {
    return colabNotebookPath;
  }
  const repo = process.env.NEXT_PUBLIC_GITHUB_REPO ?? 'https://github.com/neuralpath/neuralpath';
  const cleanRepo = repo.replace(/^https?:\/\/github\.com\//, '');
  const pathPart = colabNotebookPath
    ? colabNotebookPath.replace(/^\/+/, '')
    : 'notebooks/pytorch-sandbox.ipynb';
  return `https://colab.research.google.com/github/${cleanRepo}/blob/main/${pathPart}`;
}

